VALUES
    ('2d170af6-da34-4acc-8ed9-185abdd98c6b', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Trong các phát biểu sau, phát biểu nào đúng?', 'Trong cac phat bieu sau, phat bieu nao dung?', 'Con người sinh sản và phát triển qua các giai đoạn: sơ sinh, trẻ em, dậy thì, trưởng thành.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('05977ce8-d820-427a-9077-12fac61d74d5', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Sự thụ tinh không liên quan gì đến sinh sản. Theo em, nhận định trên đúng hay sai?', 'Su thu tinh khong lien quan gi den sinh san. Theo em, nhan dinh tren dung hay sai?', 'Sự thụ tinh là quá trình kết hợp giữa tinh trùng và trứng.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('3c7783ad-9541-45de-9ae4-03f45a95d853', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Nhận định nào sau đây là chính xác?', 'Nhan dinh nao sau day la chinh xac?', 'Năng lượng có thể chuyển từ dạng này sang dạng khác, ví dụ điện năng thành nhiệt năng.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('40b0303b-a214-405b-922a-172005b3dcbc', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Sử dụng năng lượng mặt trời là một dạng năng lượng tái tạo, thân thiện môi trường. Câu trên đúng hay sai?', 'Su dung nang luong mat troi la mot dang nang luong tai tao, than thien moi truong. Cau tren dung hay sai?', 'Sử dụng năng lượng mặt trời là một dạng năng lượng tái tạo, thân thiện môi trường.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('07fafb8a-e6a2-4cdb-8331-f9b610e23e18', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Chọn phát biểu đúng trong các phương án sau:', 'Chon phat bieu dung trong cac phuong an sau:', 'Đa dạng sinh học cần được bảo tồn để duy trì cân bằng hệ sinh thái.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('99098284-1e02-4123-9baf-d953bba8914f', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Ô nhiễm môi trường không liên quan đến hoạt động của con người. Theo em, nhận định trên đúng hay sai?', 'O nhiem moi truong khong lien quan den hoat dong cua con nguoi. Theo em, nhan dinh tren dung hay sai?', 'Ô nhiễm môi trường có thể do rác thải, khí thải công nghiệp gây ra.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('7f1a3a3a-e899-49f0-b7c7-ddaff7ce10f3', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Đâu là nhận định đúng?', 'Dau la nhan dinh dung?', 'Sử dụng tiết kiệm điện, nước là một hành động bảo vệ tài nguyên thiên nhiên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('5e05908d-3314-4111-a755-9d3d6d4c372b', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Đội mũ bảo hiểm không có tác dụng bảo vệ khi xảy ra tai nạn. Câu trên đúng hay sai?', 'Doi mu bao hiem khong co tac dung bao ve khi xay ra tai nan. Cau tren dung hay sai?', 'Đội mũ bảo hiểm khi đi xe máy, xe đạp điện giúp đảm bảo an toàn.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('30b173e0-d15a-45dc-95e3-f572b9503a86', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'essay' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Em hãy đề xuất 3 biện pháp giúp bảo vệ nguồn nước sạch ở địa phương em.', 'Em hay de xuat 3 bien phap giup bao ve nguon nuoc sach o dia phuong em.', 'Câu hỏi tự luận — chấm theo rubric của giáo viên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('6fca2fe4-4846-4d2a-948e-8392adf28c9f', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Sơ cứu đúng cách khi bị thương có thể giúp giảm nguy hiểm. Theo em, nhận định trên đúng hay sai?', 'So cuu dung cach khi bi thuong co the giup giam nguy hiem. Theo em, nhan dinh tren dung hay sai?', 'Sơ cứu đúng cách khi bị thương có thể giúp giảm nguy hiểm.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('a3a6165c-80b1-4a69-a506-2c93bf9ccd5b', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Phương án nào dưới đây là đúng?', 'Phuong an nao duoi day la dung?', 'Cây xanh giúp điều hòa không khí và giảm hiệu ứng nhà kính.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('066b1f5b-df89-4753-9256-906b09decbf8', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Chu trình nước trong tự nhiên chỉ có duy nhất giai đoạn mưa. Câu trên đúng hay sai?', 'Chu trinh nuoc trong tu nhien chi co duy nhat giai doan mua. Cau tren dung hay sai?', 'Chu trình nước trong tự nhiên gồm bay hơi, ngưng tụ và mưa.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('cc6dbee1-ec72-4bc6-9469-7c4bafc5dae9', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Ý nào sau đây phản ánh đúng nội dung đã học?', 'Y nao sau day phan anh dung noi dung da hoc?', 'Rác thải nhựa phân hủy rất chậm và gây hại cho môi trường.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('50fb8f8d-68c6-4225-bea5-8502c95b6e70', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Con người không trải qua bất kỳ giai đoạn phát triển nào. Theo em, nhận định trên đúng hay sai?', 'Con nguoi khong trai qua bat ky giai doan phat trien nao. Theo em, nhan dinh tren dung hay sai?', 'Con người sinh sản và phát triển qua các giai đoạn: sơ sinh, trẻ em, dậy thì, trưởng thành.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
