    ('b44341b7-d61f-45ad-8cef-70a47a64d802', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Hãy chỉ ra nhận định đúng trong các câu sau:', 'Hay chi ra nhan dinh dung trong cac cau sau:', 'Sơ cứu đúng cách khi bị thương có thể giúp giảm nguy hiểm.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
