    ('4bbd976b-6a4d-417f-99ae-3e10645619e4', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Ô nhiễm môi trường có thể do rác thải, khí thải công nghiệp gây ra. Theo em, nhận định trên đúng hay sai?', 'O nhiem moi truong co the do rac thai, khi thai cong nghiep gay ra. Theo em, nhan dinh tren dung hay sai?', 'Ô nhiễm môi trường có thể do rác thải, khí thải công nghiệp gây ra.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
