    ('945e1477-58df-438a-86fc-f8b495d2ada4', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Theo nội dung đã học, phát biểu nào dưới đây đúng?', 'Theo noi dung da hoc, phat bieu nao duoi day dung?', 'Đa dạng sinh học cần được bảo tồn để duy trì cân bằng hệ sinh thái.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('0b6d0fbb-a2ee-4ea9-b819-bf01c8896e63', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Ô nhiễm môi trường có thể do rác thải, khí thải công nghiệp gây ra. Câu trên đúng hay sai?', 'O nhiem moi truong co the do rac thai, khi thai cong nghiep gay ra. Cau tren dung hay sai?', 'Ô nhiễm môi trường có thể do rác thải, khí thải công nghiệp gây ra.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('3274db26-4e71-496f-b492-2d0432f1c0be', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Trong 4 phương án dưới đây, đâu là phương án đúng?', 'Trong 4 phuong an duoi day, dau la phuong an dung?', 'Sử dụng tiết kiệm điện, nước là một hành động bảo vệ tài nguyên thiên nhiên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('0b784238-3452-478a-9328-731a61f51725', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Đội mũ bảo hiểm khi đi xe máy, xe đạp điện giúp đảm bảo an toàn. Theo em, nhận định trên đúng hay sai?', 'Doi mu bao hiem khi di xe may, xe dap dien giup dam bao an toan. Theo em, nhan dinh tren dung hay sai?', 'Đội mũ bảo hiểm khi đi xe máy, xe đạp điện giúp đảm bảo an toàn.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('fdbfe7e5-2d9f-45ba-b309-8fc27ba75a94', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Hãy chỉ ra nhận định đúng trong các câu sau:', 'Hay chi ra nhan dinh dung trong cac cau sau:', 'Sơ cứu đúng cách khi bị thương có thể giúp giảm nguy hiểm.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('52658659-4680-4b36-9853-38d0528f05c9', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Cây xanh không có tác dụng gì đến chất lượng không khí. Câu trên đúng hay sai?', 'Cay xanh khong co tac dung gi den chat luong khong khi. Cau tren dung hay sai?', 'Cây xanh giúp điều hòa không khí và giảm hiệu ứng nhà kính.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('c9689d70-becd-425b-b63d-e58512077205', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Phát biểu nào dưới đây phù hợp với kiến thức đã học?', 'Phat bieu nao duoi day phu hop voi kien thuc da hoc?', 'Chu trình nước trong tự nhiên gồm bay hơi, ngưng tụ và mưa.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('e32a128c-8f97-47c0-ab79-b1e193528ae5', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Rác thải nhựa phân hủy rất chậm và gây hại cho môi trường. Theo em, nhận định trên đúng hay sai?', 'Rac thai nhua phan huy rat cham va gay hai cho moi truong. Theo em, nhan dinh tren dung hay sai?', 'Rác thải nhựa phân hủy rất chậm và gây hại cho môi trường.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
