    ('859c9fa4-c886-402f-a800-ae81731ee2a7', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Năng lượng không bao giờ chuyển đổi giữa các dạng. Theo em, nhận định trên đúng hay sai?', 'Nang luong khong bao gio chuyen doi giua cac dang. Theo em, nhan dinh tren dung hay sai?', 'Năng lượng có thể chuyển từ dạng này sang dạng khác, ví dụ điện năng thành nhiệt năng.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
