    ('5f32025c-0ba9-4d4a-9ee6-d5eaaef8b118', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Rác thải nhựa phân hủy ngay lập tức và không gây hại gì. Câu trên đúng hay sai?', 'Rac thai nhua phan huy ngay lap tuc va khong gay hai gi. Cau tren dung hay sai?', 'Rác thải nhựa phân hủy rất chậm và gây hại cho môi trường.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('23e7d06e-caf0-43e1-ad8f-75ca7fb410c5', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Xác định phát biểu đúng trong số các phương án sau:', 'Xac dinh phat bieu dung trong so cac phuong an sau:', 'Con người sinh sản và phát triển qua các giai đoạn: sơ sinh, trẻ em, dậy thì, trưởng thành.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('4f87b8ce-27ed-4d8c-b020-6cff1e73b9cb', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Sự thụ tinh là quá trình kết hợp giữa tinh trùng và trứng. Theo em, nhận định trên đúng hay sai?', 'Su thu tinh la qua trinh ket hop giua tinh trung va trung. Theo em, nhan dinh tren dung hay sai?', 'Sự thụ tinh là quá trình kết hợp giữa tinh trùng và trứng.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('fa13d15b-6b64-4f99-a853-e4b5ba430ee9', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Câu nào sau đây nêu đúng kiến thức đã học?', 'Cau nao sau day neu dung kien thuc da hoc?', 'Năng lượng có thể chuyển từ dạng này sang dạng khác, ví dụ điện năng thành nhiệt năng.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('491c5674-7724-45ff-9e78-0c83a86d71fa', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Sử dụng năng lượng mặt trời là một dạng năng lượng tái tạo, thân thiện môi trường. Câu trên đúng hay sai?', 'Su dung nang luong mat troi la mot dang nang luong tai tao, than thien moi truong. Cau tren dung hay sai?', 'Sử dụng năng lượng mặt trời là một dạng năng lượng tái tạo, thân thiện môi trường.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('feb66125-2056-483b-9d75-192fa299d099', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'essay' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Em hãy đề xuất 3 biện pháp giúp bảo vệ nguồn nước sạch ở địa phương em.', 'Em hay de xuat 3 bien phap giup bao ve nguon nuoc sach o dia phuong em.', 'Câu hỏi tự luận — chấm theo rubric của giáo viên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
