    ('5605d860-41ef-4bf6-befa-47530c25f25e', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'SCI') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'very_hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Chọn phát biểu đúng trong các phương án sau:', 'Chon phat bieu dung trong cac phuong an sau:', 'Đa dạng sinh học cần được bảo tồn để duy trì cân bằng hệ sinh thái.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Khoa học','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
